mapper.select:
SELECT id, user_id, game_key, metric_value, metric_extra, metric_json, played_count, last_played_at, created_at, updated_at FROM game_score_entry WHERE game_key = #{gameKey} ORDER BY metric_value
ASC DESC
, id ASC LIMIT #{limit}

SELECT e.id, e.user_id, CONCAT(LEFT(u.phone_number, 3), '****', RIGHT(u.phone_number, 4)) AS masked_phone, e.game_key, c.title AS game_title, e.metric_value, e.metric_extra, e.metric_json, e.played_count, e.last_played_at FROM game_score_entry e LEFT JOIN users u ON u.user_id = e.user_id LEFT JOIN game_config c ON c.game_key = e.game_key
AND e.game_key = #{gameKey}
ORDER BY e.metric_value DESC, e.id ASC
